def is_valid_weighted_checksum_ascending_mod11(s):
    if len(s) < 2:
        return False
    body = s[:-1]
    check_char = s[-1]
    if not all(ch.isdigit() for ch in body):
        return False
    weights = range(1, len(body) + 1)
    total = sum(w * int(d) for w, d in zip(weights, body))
    rem = total % 11
    return check_char == 'X' if rem == 10 else check_char == str(rem)

